/*
 * A287722  {0->1, 1->010}-transform of the infinite Fibonacci word A003849.
 * https://oeis.org/A287722
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* 
 *  a(n) = the n‑th bit of the word obtained by replacing each 0 in the
 *  Fibonacci word A003849 with 1 and each 1 with 010.
 *  The Fibonacci word is generated by the substitution 0→01, 1→0
 *  starting from the single symbol 0.  The resulting binary sequence
 *  is built incrementally and stored in a static buffer so that
 *  unrelated calls are fast.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

static uint8_t *trans_bits  = NULL; /* transformed bits 0/1           */
static idx_t     trans_len   = 0;    /* number of bits stored           */
static idx_t     trans_cap   = 0;    /* allocated capacity in bytes     */

static uint8_t *fib_prevprev = NULL; /* word F_k‑1 as bytes             */
static uint8_t *fib_prev     = NULL; /* word F_k   as bytes             */
static idx_t    fib_prevprev_len = 0;/* length of F_k‑1                  */
static idx_t    fib_prev_len     = 0;/* length of F_k                    */
static idx_t    fib_index = 0;     /* next original bit to consume     */

/* Ensure trans_bits can hold at least `min_cap` bytes. */
static void ensure_trans_capacity(idx_t min_cap)
{
    if (trans_cap >= min_cap) return;
    idx_t new_cap = trans_cap ? trans_cap << 1 : 16;
    while (new_cap < min_cap) new_cap <<= 1;
    trans_bits = (uint8_t *)realloc(trans_bits, new_cap);
    trans_cap  = new_cap;
}

/* Generate the next Fibonacci word F_{k+1} = F_k + F_{k-1}. */
static void generate_next_word(void)
{
    idx_t new_len = fib_prev_len + fib_prevprev_len;
    uint8_t *new_arr = (uint8_t *)malloc((size_t)new_len);
    if (!new_arr) return; /* should not happen in the test harness */

    memcpy(new_arr, fib_prev, (size_t)fib_prev_len);
    memcpy(new_arr + fib_prev_len, fib_prevprev, (size_t)fib_prevprev_len);

    /* shift words: new F_{k+1} becomes new prev, old prev becomes new prevprev */
    uint8_t *old_prevprev = fib_prevprev;
    fib_prevprev = fib_prev;
    fib_prev     = new_arr;

    fib_prevprev_len = fib_prev_len;
    fib_prev_len     = new_len;

    free(old_prevprev);
}

/* Static initialisation of the Fibonacci word generators. */
static void init_static(void)
{
    if (fib_prevprev) return; /* already initialised */

    /* F_0 = 0 */
    fib_prevprev = (uint8_t *)malloc(1);
    fib_prevprev[0] = 0;
    fib_prevprev_len = 1;

    /* F_1 = 01 */
    fib_prev = (uint8_t *)malloc(2);
    fib_prev[0] = 0;
    fib_prev[1] = 1;
    fib_prev_len = 2;

    fib_index = 0;
}

/* --- public function ---------------------------------------------------- */
seq_t a(idx_t n)
{
    if (n == 0) return 0; /* offset 1, no value for n=0 */

    init_static();

    /* Generate transformed bits until we have at least n of them. */
    while (trans_len < n) {
        /* If we have consumed all bits of the current Fibonacci word,
           generate the next word. */
        if (fib_index >= fib_prev_len)
            generate_next_word();

        uint8_t orig_bit = fib_prev[fib_index++];
        if (orig_bit == 0) {
            ensure_trans_capacity(trans_len + 1);
            trans_bits[trans_len++] = 1;   /* 0 -> 1 */
        } else {
            ensure_trans_capacity(trans_len + 3);
            trans_bits[trans_len++] = 0;   /* 1 -> 0 1 0 */
            trans_bits[trans_len++] = 1;
            trans_bits[trans_len++] = 0;
        }
    }

    /* Return the requested value (check cast will work for any seq_t). */
    return (seq_t)trans_bits[n - 1];
}
